FUNCTION_BLOCK FB_MultiLaserPBF_StitchingSync
(*
 ====================================================================================================
 ARCHITECTURE: Cyber-Physical Multi-Laser Additive Manufacturing Controller
 SUBSYSTEM   : Dual-Galvanometer Optical Synchronization & Boundary Stitching Thermal Overlap MPC
 STANDARD    : IEC 61131-3 3rd Ed. (Deterministic Hard Real-Time 50 us Cycle Task)
 SAFETY CLASS: SIL-3 / IEC 61508 / ISO 13849-1 Category 4 PLe Fault-Tolerant Architecture
 ----------------------------------------------------------------------------------------------------
 DESCRIPTION :
   Orchestrates dual fiber laser (L1, L2) galvanometer optical scanners operating across overlapping
   build envelopes in Powder Bed Fusion of Metals (PBF-LB/M). Integrates:
     1. Triple Modular Redundant (2oo3 TMR) fast coaxial pyrometry voting for melt pool monitoring.
     2. Thermo-optical drift compensation for dynamic F-theta / telecentric scan lens expansion.
     3. Reduced-Order State-Space Model Predictive Control (MPC) predicting thermal accumulation
        in the shared stitching boundary to eliminate keyhole depression, spatter ejection,
        and lack-of-fusion voids.
     4. Shield gas plume aerodynamic vector shadowing compensation (cross-flow argon velocity).
     5. Graceful degradation to serialized single-beam scanning upon optical discrepancy or actuator trip.
 ====================================================================================================
*)

VAR_INPUT
    bEnable                     : BOOL;     (* Master process enable command from CNC supervisor *)
    bEmergencyStop              : BOOL;     (* Fail-safe dual-channel E-stop relay contact: TRUE = Healthy [SIL-3] *)
    bLaser1_Armed               : BOOL;     (* Laser source 1 interlock loop and diode driver ready *)
    bLaser2_Armed               : BOOL;     (* Laser source 2 interlock loop and diode driver ready *)
    rPowerSet_L1                : REAL;     (* Commanded nominal optical power Laser 1 [W] (Range: 50.0..1000.0) *)
    rPowerSet_L2                : REAL;     (* Commanded nominal optical power Laser 2 [W] (Range: 50.0..1000.0) *)
    rScanSpeed_L1               : REAL;     (* Commanded vector velocity Laser 1 [mm/s] (Range: 100.0..5000.0) *)
    rScanSpeed_L2               : REAL;     (* Commanded vector velocity Laser 2 [mm/s] (Range: 100.0..5000.0) *)
    rPosCmdX_L1                 : REAL;     (* Commanded target coordinate X for Laser 1 [um] *)
    rPosCmdY_L1                 : REAL;     (* Commanded target coordinate Y for Laser 1 [um] *)
    rPosCmdX_L2                 : REAL;     (* Commanded target coordinate X for Laser 2 [um] *)
    rPosCmdY_L2                 : REAL;     (* Commanded target coordinate Y for Laser 2 [um] *)
    rChamberPressure_mbar       : REAL;     (* Process chamber absolute static inert gas pressure [mbar] *)
    rChamberO2_ppm              : REAL;     (* Residual oxygen concentration in recirculating loop [ppm] *)
    rGasFlowVelocity_mps        : REAL;     (* Laminar argon protective cross-flow velocity across bed [m/s] *)
    rBedPreheatTemp_degC        : REAL;     (* Build substrate baseplate resistance heater temperature [deg C] *)
    rPyrometer_S1_degC          : REAL;     (* Coaxial NIR photodiode sensor channel 1 melt temperature [deg C] *)
    rPyrometer_S2_degC          : REAL;     (* Coaxial NIR photodiode sensor channel 2 melt temperature [deg C] *)
    rPyrometer_S3_degC          : REAL;     (* Coaxial NIR photodiode sensor channel 3 melt temperature [deg C] *)
    rGalvoTemp_L1_degC          : REAL;     (* Scan head 1 galvanometer mirror drive core temperature [deg C] *)
    rGalvoTemp_L2_degC          : REAL;     (* Scan head 2 galvanometer mirror drive core temperature [deg C] *)
    rStitchZoneX_Min_um         : REAL;     (* Overlap boundary spatial envelope lower X boundary [um] *)
    rStitchZoneX_Max_um         : REAL;     (* Overlap boundary spatial envelope upper X boundary [um] *)
    rMaxAllowableMeltTemp_degC  : REAL;     (* Upper thermal ceiling before keyhole vaporization trip [deg C] *)
    rMinFusionMeltTemp_degC     : REAL;     (* Lower thermal floor required to guarantee complete fusion [deg C] *)
END_VAR

VAR_OUTPUT
    bSystemReady                : BOOL;     (* All pre-requisites, safety interlocks, and buffers verified *)
    bStitchActive               : BOOL;     (* Both beams concurrently traversing stitching boundary *)
    rModulatedPower_L1          : REAL;     (* Real-time thermal-compensated optical power for Laser 1 [W] *)
    rModulatedPower_L2          : REAL;     (* Real-time thermal-compensated optical power for Laser 2 [W] *)
    rSyncPosX_L1                : REAL;     (* Thermally compensated and synchronized galvo coordinate X1 [um] *)
    rSyncPosY_L1                : REAL;     (* Thermally compensated and synchronized galvo coordinate Y1 [um] *)
    rSyncPosX_L2                : REAL;     (* Thermally compensated and synchronized galvo coordinate X2 [um] *)
    rSyncPosY_L2                : REAL;     (* Thermally compensated and synchronized galvo coordinate Y2 [um] *)
    rVotedMeltTemp_degC         : REAL;     (* 2oo3 TMR validated instantaneous melt pool temperature [deg C] *)
    rInterLaserDistance_um      : REAL;     (* Instantaneous Euclidean focal spot separation distance [um] *)
    wDiagnosticWord             : WORD;     (* Status bitmask: Bit0=Run, Bit1=Stitch, Bit2=TMR_Degraded, etc. *)
    wAlarmCode                  : WORD;     (* Active industrial fault code: 0=None, 16#E001..16#EFFF *)
    bAlarmTripped               : BOOL;     (* Critical safety or process deviation interlock trip flag *)
    bDegradedModeActive         : BOOL;     (* Graceful single-laser serialized stitching mode active *)
END_VAR

VAR
    (* Sequencer State Definitions *)
    iState                      : INT := 0;     (* Primary finite state machine supervisor index *)
    iSubState                   : INT := 0;     (* Sub-sequencer step index *)
    iPreviousState              : INT := 0;     (* State history tracker for transition validation *)

    (* Timers for Process Latencies & Safety Timeouts *)
    tChamberSettleTimer         : TON;          (* Atmosphere conditioning stabilization timer *)
    tStitchDwellTimer           : TON;          (* Interleaving thermal relaxation pause timer *)
    tWatchdogTimer              : TON;          (* Communications and trajectory sync watchdog *)
    tDegradedModeTimer          : TON;          (* Degraded mode transition dwell timer *)

    (* 2oo3 Triple Modular Redundancy (TMR) Voting Architecture *)
    bS1_Valid                   : BOOL;         (* Pyrometer channel 1 operational status *)
    bS2_Valid                   : BOOL;         (* Pyrometer channel 2 operational status *)
    bS3_Valid                   : BOOL;         (* Pyrometer channel 3 operational status *)
    rDiff12                     : REAL;         (* Channel 1 vs Channel 2 deviation [deg C] *)
    rDiff23                     : REAL;         (* Channel 2 vs Channel 3 deviation [deg C] *)
    rDiff13                     : REAL;         (* Channel 1 vs Channel 3 deviation [deg C] *)
    rTMR_Tolerance_degC         : REAL := 75.0; (* Discrepancy tolerance limit between redundant pyrometers *)
    iValidSensorsCount          : INT;          (* Count of mutually agreeing sensor channels *)

    (* Galvanometer Structural & Optical Thermal Drift Compensation *)
    rNominalGalvoTemp_degC      : REAL := 25.0; (* Calibrated factory reference temperature of galvo body [deg C] *)
    rThermalCoeff_ppm_K         : REAL := 9.4;  (* CTE of scan mirror mounts and F-theta housing [ppm/K] *)
    rEffectiveFocalLength_um    : REAL := 420000.0; (* Effective optical focal length F = 420 mm [um] *)
    rDriftOffset_X1             : REAL;         (* Corrected drift vector X for scan head 1 [um] *)
    rDriftOffset_Y1             : REAL;         (* Corrected drift vector Y for scan head 1 [um] *)
    rDriftOffset_X2             : REAL;         (* Corrected drift vector X for scan head 2 [um] *)
    rDriftOffset_Y2             : REAL;         (* Corrected drift vector Y for scan head 2 [um] *)

    (* Model Predictive Control (MPC) / Reduced-Order State-Space Thermal Observer *)
    (* State vector: x[1] = T_peak [deg C], x[2] = dT/dt [deg C/s], x[3] = Enthalpy_Accum, x[4] = MeltWidth [um] *)
    x_state                     : ARRAY[1..4] OF REAL;
    x_pred                      : ARRAY[1..4] OF REAL;
    A_mat                       : ARRAY[1..4, 1..4] OF REAL; (* Discrete state transition matrix (50 us Ts) *)
    B_mat                       : ARRAY[1..4, 1..2] OF REAL; (* Input coupling matrix for [P_L1, P_L2] *)
    C_vec                       : ARRAY[1..4] OF REAL;       (* Output observation vector *)
    rThermalInteractionFactor   : REAL;         (* Spatial proximity coupling coefficient [0.0..1.0] *)
    rDecayTau_s                 : REAL := 0.00180; (* Thermal relaxation time constant of metal alloy [s] *)
    rProximityRadius_um         : REAL := 2500.0;  (* Critical interaction boundary radius [um] *)

    (* Plume Aerodynamics & Laser Shadowing Geometry *)
    rDeltaX_Positions           : REAL;         (* X spatial separation between focal points [um] *)
    rDeltaY_Positions           : REAL;         (* Y spatial separation between focal points [um] *)
    bPlumeInterferenceActive    : BOOL;         (* TRUE when Laser 2 path crosses Laser 1 fume plume *)
    rPlumeExtinctionCorrection  : REAL;         (* Power boost coefficient compensating for fume attenuation *)

    (* Power Modulation Gains & Filters *)
    rCalculatedAtten_L1         : REAL;         (* Fractional thermal throttling factor L1 [0.4..1.0] *)
    rCalculatedAtten_L2         : REAL;         (* Fractional thermal throttling factor L2 [0.4..1.0] *)
    rFilteredMeltTemp           : REAL;         (* First-order lag filtered melt pool temperature [deg C] *)
    rFilterAlpha                : REAL := 0.15; (* Low-pass filter smoothing coefficient *)
END_VAR

(* === RE-ENTRANT CONTROL LOGIC ENTRY POINT === *)

(* ====================================================================================================
   SECTION 1: FAIL-SAFE INTERLOCKS & HARDWARE LEVEL DISPATCH
   ==================================================================================================== *)
IF NOT bEmergencyStop THEN
    (* Immediate deterministic hardware safe state: zero laser optical excitation & latch alarm *)
    rModulatedPower_L1    := 0.0;
    rModulatedPower_L2    := 0.0;
    rSyncPosX_L1          := 0.0;
    rSyncPosY_L1          := 0.0;
    rSyncPosX_L2          := 0.0;
    rSyncPosY_L2          := 0.0;
    bSystemReady          := FALSE;
    bStitchActive         := FALSE;
    bAlarmTripped         := TRUE;
    wAlarmCode            := 16#E001; (* EMERGENCY_STOP_OPEN_CIRCUIT *)
    wDiagnosticWord       := 16#8000; (* Bit 15: Critical Fault Latched *)
    iState                := 99;      (* Safe State Lockout *)
    RETURN;
END_IF;

(* Evaluate Process Environment Atmospheric Constraints *)
IF (rChamberPressure_mbar < 1005.0) OR (rChamberPressure_mbar > 1040.0) THEN
    bAlarmTripped   := TRUE;
    wAlarmCode      := 16#E002; (* CHAMBER_PRESSURE_OUT_OF_BOUNDS *)
    iState          := 99;
    RETURN;
END_IF;

IF rChamberO2_ppm > 80.0 THEN
    bAlarmTripped   := TRUE;
    wAlarmCode      := 16#E003; (* ATMOSPHERE_O2_CONTAMINATION_HIGH *)
    iState          := 99;
    RETURN;
END_IF;

(* ====================================================================================================
   SECTION 2: TRIPLE MODULAR REDUNDANCY (2oo3) FAST PYROMETRY VOTING ENGINE
   ==================================================================================================== *)
rDiff12 := ABS(rPyrometer_S1_degC - rPyrometer_S2_degC);
rDiff23 := ABS(rPyrometer_S2_degC - rPyrometer_S3_degC);
rDiff13 := ABS(rPyrometer_S1_degC - rPyrometer_S3_degC);

bS1_Valid := (rDiff12 <= rTMR_Tolerance_degC) OR (rDiff13 <= rTMR_Tolerance_degC);
bS2_Valid := (rDiff12 <= rTMR_Tolerance_degC) OR (rDiff23 <= rTMR_Tolerance_degC);
bS3_Valid := (rDiff13 <= rTMR_Tolerance_degC) OR (rDiff23 <= rTMR_Tolerance_degC);

iValidSensorsCount := BOOL_TO_INT(bS1_Valid) + BOOL_TO_INT(bS2_Valid) + BOOL_TO_INT(bS3_Valid);

IF (bS1_Valid AND bS2_Valid AND bS3_Valid) THEN
    (* Median selection across all three healthy channels *)
    IF ((rPyrometer_S1_degC >= rPyrometer_S2_degC) AND (rPyrometer_S1_degC <= rPyrometer_S3_degC)) OR
       ((rPyrometer_S1_degC <= rPyrometer_S2_degC) AND (rPyrometer_S1_degC >= rPyrometer_S3_degC)) THEN
        rVotedMeltTemp_degC := rPyrometer_S1_degC;
    ELSIF ((rPyrometer_S2_degC >= rPyrometer_S1_degC) AND (rPyrometer_S2_degC <= rPyrometer_S3_degC)) OR
          ((rPyrometer_S2_degC <= rPyrometer_S1_degC) AND (rPyrometer_S2_degC >= rPyrometer_S3_degC)) THEN
        rVotedMeltTemp_degC := rPyrometer_S2_degC;
    ELSE
        rVotedMeltTemp_degC := rPyrometer_S3_degC;
    END_IF;
    wDiagnosticWord := wDiagnosticWord AND 16#FFFB; (* Clear Bit 2: TMR Healthy *)
ELSIF (bS1_Valid AND bS2_Valid) THEN
    rVotedMeltTemp_degC := (rPyrometer_S1_degC + rPyrometer_S2_degC) * 0.5;
    wDiagnosticWord := wDiagnosticWord OR 16#0004;  (* Set Bit 2: TMR Channel 3 Degraded *)
ELSIF (bS2_Valid AND bS3_Valid) THEN
    rVotedMeltTemp_degC := (rPyrometer_S2_degC + rPyrometer_S3_degC) * 0.5;
    wDiagnosticWord := wDiagnosticWord OR 16#0004;  (* Set Bit 2: TMR Channel 1 Degraded *)
ELSIF (bS1_Valid AND bS3_Valid) THEN
    rVotedMeltTemp_degC := (rPyrometer_S1_degC + rPyrometer_S3_degC) * 0.5;
    wDiagnosticWord := wDiagnosticWord OR 16#0004;  (* Set Bit 2: TMR Channel 2 Degraded *)
ELSE
    (* Total Sensor Divergence: Trip safety to prevent unmonitored runaway *)
    bAlarmTripped       := TRUE;
    wAlarmCode          := 16#E004; (* TMR_PYROMETRY_COMMON_CAUSE_FAILURE *)
    rModulatedPower_L1  := 0.0;
    rModulatedPower_L2  := 0.0;
    iState              := 99;
    RETURN;
END_IF;

(* First-Order Exponential Lag Filter on Validated Pyrometry *)
rFilteredMeltTemp := (rFilterAlpha * rVotedMeltTemp_degC) + ((1.0 - rFilterAlpha) * rFilteredMeltTemp);

(* ====================================================================================================
   SECTION 3: GALVANOMETER THERMAL DRIFT & PARALLAX EXPANSION MATRIX
   ==================================================================================================== *)
(* Optical expansion scaling: Delta_Offset = FocalLength * alpha * Delta_T * (Pos / ScanRadius) *)
rDriftOffset_X1 := (rEffectiveFocalLength_um * (rThermalCoeff_ppm_K * 1.0E-6) * (rGalvoTemp_L1_degC - rNominalGalvoTemp_degC)) * (rPosCmdX_L1 / 250000.0);
rDriftOffset_Y1 := (rEffectiveFocalLength_um * (rThermalCoeff_ppm_K * 1.0E-6) * (rGalvoTemp_L1_degC - rNominalGalvoTemp_degC)) * (rPosCmdY_L1 / 250000.0);
rDriftOffset_X2 := (rEffectiveFocalLength_um * (rThermalCoeff_ppm_K * 1.0E-6) * (rGalvoTemp_L2_degC - rNominalGalvoTemp_degC)) * (rPosCmdX_L2 / 250000.0);
rDriftOffset_Y2 := (rEffectiveFocalLength_um * (rThermalCoeff_ppm_K * 1.0E-6) * (rGalvoTemp_L2_degC - rNominalGalvoTemp_degC)) * (rPosCmdY_L2 / 250000.0);

rSyncPosX_L1 := rPosCmdX_L1 - rDriftOffset_X1;
rSyncPosY_L1 := rPosCmdY_L1 - rDriftOffset_Y1;
rSyncPosX_L2 := rPosCmdX_L2 - rDriftOffset_X2;
rSyncPosY_L2 := rPosCmdY_L2 - rDriftOffset_Y2;

(* Euclidean Distance between Laser 1 and Laser 2 Spot Coordinates *)
rDeltaX_Positions := rSyncPosX_L1 - rSyncPosX_L2;
rDeltaY_Positions := rSyncPosY_L1 - rSyncPosY_L2;
rInterLaserDistance_um := SQRT((rDeltaX_Positions * rDeltaX_Positions) + (rDeltaY_Positions * rDeltaY_Positions));

(* Plume Vector Shadowing Evaluation: Laminar Gas Flow in +X direction *)
(* If Laser 2 is downstream (X2 > X1) and Y separation is within the turbulent wake width (< 800 um) *)
IF (rSyncPosX_L2 > rSyncPosX_L1) AND (ABS(rDeltaY_Positions) < 800.0) AND (rGasFlowVelocity_mps > 1.0) THEN
    bPlumeInterferenceActive := TRUE;
    rPlumeExtinctionCorrection := 1.065; (* 6.5% boost to compensate for condensate optical scatter *)
ELSE
    bPlumeInterferenceActive := FALSE;
    rPlumeExtinctionCorrection := 1.000;
END_IF;

(* ====================================================================================================
   SECTION 4: REDUCED-ORDER STATE-SPACE MODEL PREDICTIVE CONTROLLER (MPC)
   ==================================================================================================== *)
(* Discrete State Matrices for Ti-6Al-4V powder bed thermal diffusion (Ts = 50 us) *)
A_mat[1,1] := 0.9420; A_mat[1,2] := 0.000045; A_mat[1,3] := 0.0120; A_mat[1,4] := -0.0050;
A_mat[2,1] := -1.150; A_mat[2,2] := 0.885000; A_mat[2,3] := 0.2500; A_mat[2,4] := -0.1200;
A_mat[3,1] := 0.0180; A_mat[3,2] := 0.000008; A_mat[3,3] := 0.9910; A_mat[3,4] := 0.0020;
A_mat[4,1] := 0.0450; A_mat[4,2] := 0.000010; A_mat[4,3] := 0.0080; A_mat[4,4] := 0.9350;

B_mat[1,1] := 0.1850; B_mat[1,2] := 0.1850;
B_mat[2,1] := 3.4200; B_mat[2,2] := 3.4200;
B_mat[3,1] := 0.0240; B_mat[3,2] := 0.0240;
B_mat[4,1] := 0.0820; B_mat[4,2] := 0.0820;

C_vec[1]   := 1.0;    C_vec[2]   := 0.0;      C_vec[3]   := 0.05;   C_vec[4]   := 0.0;

(* Spatial proximity thermal overlap factor based on Rosenthal point-source decay *)
IF rInterLaserDistance_um < rProximityRadius_um THEN
    rThermalInteractionFactor := (rProximityRadius_um - rInterLaserDistance_um) / rProximityRadius_um;
ELSE
    rThermalInteractionFactor := 0.0;
END_IF;

(* Forward State Estimation x_pred(k+1) = A * x(k) + B * u(k) *)
x_pred[1] := (A_mat[1,1] * x_state[1]) + (A_mat[1,2] * x_state[2]) + (A_mat[1,3] * x_state[3]) + (A_mat[1,4] * x_state[4])
             + (B_mat[1,1] * rPowerSet_L1 * (1.0 + rThermalInteractionFactor)) + (B_mat[1,2] * rPowerSet_L2 * (1.0 + rThermalInteractionFactor));

x_pred[2] := (A_mat[2,1] * x_state[1]) + (A_mat[2,2] * x_state[2]) + (A_mat[2,3] * x_state[3]) + (A_mat[2,4] * x_state[4])
             + (B_mat[2,1] * rPowerSet_L1) + (B_mat[2,2] * rPowerSet_L2);

x_pred[3] := (A_mat[3,1] * x_state[1]) + (A_mat[3,2] * x_state[2]) + (A_mat[3,3] * x_state[3]) + (A_mat[3,4] * x_state[4])
             + (B_mat[3,1] * rPowerSet_L1) + (B_mat[3,2] * rPowerSet_L2);

x_pred[4] := (A_mat[4,1] * x_state[1]) + (A_mat[4,2] * x_state[2]) + (A_mat[4,3] * x_state[3]) + (A_mat[4,4] * x_state[4])
             + (B_mat[4,1] * rPowerSet_L1) + (B_mat[4,2] * rPowerSet_L2);

(* Observer State Correction with 2oo3 Filtered Measurement Feedback *)
x_state[1] := x_pred[1] + 0.12 * (rFilteredMeltTemp - x_pred[1]);
x_state[2] := x_pred[2] + 0.08 * ((rFilteredMeltTemp - x_pred[1]) / 0.000050);
x_state[3] := x_pred[3];
x_state[4] := x_pred[4];

(* Compute Predictive Overlap Attenuation Factor *)
IF x_state[1] > (rMaxAllowableMeltTemp_degC - 100.0) THEN
    (* Linear gradient reduction to arrest keyhole onset *)
    rCalculatedAtten_L1 := 1.0 - ((x_state[1] - (rMaxAllowableMeltTemp_degC - 100.0)) / 250.0);
    IF rCalculatedAtten_L1 < 0.45 THEN
        rCalculatedAtten_L1 := 0.45; (* Hard floor to maintain minimum required fusion energy *)
    END_IF;
    rCalculatedAtten_L2 := rCalculatedAtten_L1;
ELSE
    rCalculatedAtten_L1 := 1.00;
    rCalculatedAtten_L2 := 1.00;
END_IF;

(* ====================================================================================================
   SECTION 5: INDUSTRIAL FINITE STATE MACHINE SEQUENCER
   ==================================================================================================== *)
CASE iState OF

    0: (* SYSTEM INITIALIZATION & INTEGRITY CHECK *)
        bSystemReady            := FALSE;
        bStitchActive           := FALSE;
        bDegradedModeActive     := FALSE;
        bAlarmTripped           := FALSE;
        wAlarmCode              := 0;
        wDiagnosticWord         := 16#0000;
        rModulatedPower_L1      := 0.0;
        rModulatedPower_L2      := 0.0;
        x_state[1]              := rBedPreheatTemp_degC;
        x_state[2]              := 0.0;
        x_state[3]              := 0.0;
        x_state[4]              := 100.0; (* Base beam spot diameter 100 um *)

        tChamberSettleTimer(IN := FALSE, PT := T#2S);

        IF bEnable AND (rBedPreheatTemp_degC >= 180.0) THEN
            iState := 10; (* Transition to Inerting Verification *)
        END_IF;

    10: (* INERT ATMOSPHERE & FLOW VELOCITY VALIDATION *)
        tChamberSettleTimer(IN := TRUE, PT := T#1500MS);
        IF (rGasFlowVelocity_mps >= 1.5) AND (rGasFlowVelocity_mps <= 3.8) AND
           (rChamberO2_ppm <= 40.0) AND tChamberSettleTimer.Q THEN
            tChamberSettleTimer(IN := FALSE);
            iState := 20; (* Transition to Laser Source Arming *)
        ELSIF tChamberSettleTimer.Q THEN
            bAlarmTripped   := TRUE;
            wAlarmCode      := 16#E010; (* INERTING_FLOW_STABILIZATION_TIMEOUT *)
            iState          := 99;
        END_IF;

    20: (* DUAL OPTICAL SOURCE SYNCHRONIZATION STANDBY *)
        IF bLaser1_Armed AND bLaser2_Armed THEN
            bSystemReady    := TRUE;
            wDiagnosticWord := wDiagnosticWord OR 16#0001; (* Bit 0: System Running & Ready *)
            iState          := 30; (* Advance to Active Scan Coordination *)
        ELSE
            bSystemReady    := FALSE;
            wDiagnosticWord := wDiagnosticWord AND 16#FFFE;
            IF NOT bEnable THEN
                iState := 0;
            END_IF;
        END_IF;

    30: (* SYNCHRONIZED VECTOR SCANNING *)
        bSystemReady := TRUE;
        (* Boundary Evaluation: Check if either beam is within stitching overlap zone *)
        IF ((rSyncPosX_L1 >= rStitchZoneX_Min_um) AND (rSyncPosX_L1 <= rStitchZoneX_Max_um)) AND
           ((rSyncPosX_L2 >= rStitchZoneX_Min_um) AND (rSyncPosX_L2 <= rStitchZoneX_Max_um)) THEN
            bStitchActive   := TRUE;
            wDiagnosticWord := wDiagnosticWord OR 16#0002; (* Bit 1: Stitch Active *)
            iState          := 40; (* Enter Precision Stitching Thermal Control *)
        ELSE
            bStitchActive   := FALSE;
            wDiagnosticWord := wDiagnosticWord AND 16#FFFD;
            (* Baseline Nominal Laser Power with Plume Compensation *)
            rModulatedPower_L1 := rPowerSet_L1;
            rModulatedPower_L2 := rPowerSet_L2 * rPlumeExtinctionCorrection;
        END_IF;

        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    40: (* STITCHING BOUNDARY THERMAL OVERLAP CONTROL *)
        bStitchActive := TRUE;

        (* Inter-Laser Proximity Interlock: Avoid direct optical spot collision (< 150 um) *)
        IF rInterLaserDistance_um < 150.0 THEN
            (* Direct collision risk: switch Laser 2 into Temporal Interleaving Hold *)
            rModulatedPower_L1 := rPowerSet_L1 * 0.85;
            rModulatedPower_L2 := 0.0; (* Blank laser 2 gate *)
            iState := 80;              (* Hold and Stagger *)
        ELSE
            (* Apply Full MPC Multi-Laser Power Modulation *)
            rModulatedPower_L1 := rPowerSet_L1 * rCalculatedAtten_L1;
            rModulatedPower_L2 := rPowerSet_L2 * rCalculatedAtten_L2 * rPlumeExtinctionCorrection;
        END_IF;

        (* Real-time Melt Pool Temperature Deviation Supervision *)
        IF rFilteredMeltTemp > rMaxAllowableMeltTemp_degC THEN
            (* Incipient Keyholing / Vaporization: Force immediate thermal relief *)
            rModulatedPower_L1 := rModulatedPower_L1 * 0.70;
            rModulatedPower_L2 := rModulatedPower_L2 * 0.70;
            wDiagnosticWord    := wDiagnosticWord OR 16#0010; (* Bit 4: Thermal Relief Active *)
        ELSIF rFilteredMeltTemp < rMinFusionMeltTemp_degC THEN
            (* Lack of Fusion Warning *)
            wDiagnosticWord    := wDiagnosticWord OR 16#0020; (* Bit 5: Lack of Fusion Risk *)
        END_IF;

        (* Check if both scan heads have navigated outside stitching corridor *)
        IF NOT (((rSyncPosX_L1 >= rStitchZoneX_Min_um) AND (rSyncPosX_L1 <= rStitchZoneX_Max_um)) AND
                ((rSyncPosX_L2 >= rStitchZoneX_Min_um) AND (rSyncPosX_L2 <= rStitchZoneX_Max_um))) THEN
            bStitchActive := FALSE;
            wDiagnosticWord := wDiagnosticWord AND 16#FFFD;
            iState := 30; (* Return to Standard Synchronized Scanning *)
        END_IF;

    80: (* TEMPORAL INTERLEAVING HOLD (HEAT DISSIPATION PAUSE) *)
        tStitchDwellTimer(IN := TRUE, PT := T#450US);
